__NUXT_JSONP__("/posts/testing-a-headless-architecture-with-nuxt-prismic", (function(a,b,c,d,e,f,g,h,i,j,k,l,m,n,o,p,q,r,s,t,u,v,w,x,y,z,A,B,C,D,E,F,G,H,I,J,K,L,M){return {data:[{post:{slug:u,description:"This last month, I had the opportunity to finally test a headless architecture for a B2B single page website marketpay.eu.\nThe page content should be editable by external contributors using a content management system.",title:"Testing a headless architecture with Nuxt + Prismic",type:j,imgCover:u,tags:["netlify","prismic",s,t,j],createdAt:"2020-04-02T00:00:00.000Z",toc:[{id:v,depth:l,text:w},{id:x,depth:l,text:y},{id:z,depth:l,text:A},{id:B,depth:l,text:C},{id:D,depth:l,text:E}],body:{type:F,children:[{type:b,tag:e,props:{},children:[{type:a,value:G},{type:b,tag:d,props:{href:H,rel:[f,g,h],target:i},children:[{type:a,value:I}]},{type:a,value:J}]},{type:a,value:c},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"So far, I only used Wordpress to deploy website with editing capabilities. But times are changing and my tool of choice to build website has become Vue. The solution is to couple the Vue front-end with what is called a \"headless CMS\"."}]},{type:a,value:c},{type:b,tag:m,props:{id:v},children:[{type:b,tag:d,props:{href:"#prismic-as-headless-cms",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:w}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"With the rise of javascript frameworks, a lot of headless CMS have popped out to replace traditional monolith CMS such as Drupal or Wordpress. The website "},{type:b,tag:d,props:{href:"https:\u002F\u002Fheadlesscms.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"headlesscms.org"}]},{type:a,value:" list all those tools classified by trend usages."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"In the past, I’ve quickly boot-started "},{type:b,tag:d,props:{href:"https:\u002F\u002Fstrapi.io\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Strapi"}]},{type:a,value:" but I gave up considering the numerous bugs I’ve encountered (mostly bugs during deploys but within the CMS experience as well). Strapi is an open source solution, it’s a bit difficult to setup because we have the responsibility of a Mongo database management on top of it."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fprismic.io\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Prismic"}]},{type:a,value:" is a french tech company providing an API-based headless CMS as a SaaS platform. It has an intuitive and a neat interface that offers a smooth experience while setting up content for our project. The free-tiers offers more than enough to get started, and the first paid plan is very affordable."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I found their documentation is very clear and covers all the features in a clear manner. This CMS is also very versatile and can be coupled with various techs. In my case, I used a Nuxt.js starter that is a great help to understand all things work without headaches. The documentation also offers videos and user-guides to help us get started."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The project I've been working on should also supports both EN+FR languages. The Prismic multi-language feature is well designed, and directly available from the Prismic top-bar while editing a document. The colors play a huge role in the Prismic admin UI as its toggle from green to yellow everytime we make a change."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"At the end, I’m very satisfied of the experience Prismic has to offer."}]},{type:a,value:c},{type:b,tag:m,props:{id:x},children:[{type:b,tag:d,props:{href:"#server-side-rendering-with-nuxt",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:y}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"So far, I used Nuxt.js on top of Vue because of the pleasant abstraction it offers in terms of directory structure, configuration file and so on.. But I only used it for SPA or static generated site. This time, we have a site that might be updated frequently by external contributors and should also be crawlable by search engines for SEO. I had to use the SSR capabilities to respond to this need. The Prismic Nuxt starter encompasses a preview feature that require SSR to work with."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Switching to SSR development is not that different from a SPA usage, the main difference is that the page are server-render at first load, so we have to use the terminal to show our debug logs instead of the browser console. We should also care about plugins which have to render on the client-side only, not a big deal with the ≶client-only\u003E tag or suffix our plugin files with \".client\"."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The main concern is also the hosting platform on which our app will live, as we will need a node server. The easier deployment solution is to use Heroku which is a PaaS cloud platform with a neat interface. We can use its CLI that offers a convenient deployment pipeline."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"However and for my case, the client wanted to manage the hosting himself so I deployed on a Gitlab repo, and the client care about deploying the app on a Google engine instance, which is another cloud platform."}]},{type:a,value:c},{type:b,tag:m,props:{id:z},children:[{type:b,tag:d,props:{href:"#mastering-complex-forms-using-phpnode",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:A}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Before this project, I had to deal with several pages including complex contact forms. These forms includes conditional display, advanced components and re-captcha test. As things progress, I improved the way I build form. I started to \"componentize\" each input and deal with implementing Vue v-model to child components."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"I always use "},{type:b,tag:d,props:{href:"https:\u002F\u002Fvuelidate.js.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Vuelidate"}]},{type:a,value:" as a validation tool and have experienced a lot of use-cases (basic input, input types, checkbox, radio, select, conditional validations, custom validations..)"}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"Lately, I read a very helpful book about "},{type:b,tag:d,props:{href:"https:\u002F\u002Fwww.amazon.fr\u002FBuilding-Forms-Vue-js-Patterns-building-ebook\u002Fdp\u002FB07YY7MGDD",rel:[f,g,h],target:i},children:[{type:a,value:"building form in Vue.js"}]},{type:a,value:". It helped me to have a better grasp of how v-model works and how to use Vuelidate in a nested component hierarchy. It also has an interesting part about building an api-driven form, which will be my next code improvement."}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The form submission to the server is handed with the "},{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Faxios\u002Faxios",rel:[f,g,h],target:i},children:[{type:a,value:"Axios"}]},{type:a,value:" library. I implemented the server-side processing in both PHP and Node.js according to the hosting environment. There is two use-cases :"}]},{type:a,value:c},{type:b,tag:K,props:{},children:[{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"The re-captcha validation (the server-side verification to handle a response)"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:a,value:"The form submission itself. For the latest, I use "},{type:b,tag:d,props:{href:"https:\u002F\u002Ffr.sendinblue.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Send In Blue"}]},{type:a,value:" as a mail sender, from which we can leverage their mail templating system handling dynamic variables."}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"The Node.js implementation of the server-side form processing has been the opportunity to learn the basics of "},{type:b,tag:d,props:{href:"https:\u002F\u002Fexpressjs.com\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Express.js"}]},{type:a,value:", and how the app.post method handle routes. Not a big deal so far. I advise the concise "},{type:b,tag:d,props:{href:"https:\u002F\u002Fflaviocopes.com\u002Fpage\u002Fexpress-handbook\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Express Handbook from Flavio"}]},{type:a,value:", available as e-book, a perfect resource to start with Express.js."}]},{type:a,value:c},{type:b,tag:m,props:{id:B},children:[{type:b,tag:d,props:{href:"#vue-library-round-up",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:C}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"With every project comes a lot of third-party tools and here is some of them I used and approved along the way :"}]},{type:a,value:c},{type:b,tag:K,props:{},children:[{type:a,value:c},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fmichalsnik.github.io\u002Faos\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"AOS"}]},{type:a,value:" : A complete and simple on-scroll-reveal tool"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fkazupon.github.io\u002Fvue-i18n\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"I18n"}]},{type:a,value:" : The official package to serve translations from locales"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Falexjoverm\u002Fv-lazy-image",rel:[f,g,h],target:i},children:[{type:a,value:"v-lazy-image"}]},{type:a,value:" : A simple package to automatically handle lazy-loaded images"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Feuvl\u002Fvue-js-modal",rel:[f,g,h],target:i},children:[{type:a,value:"vue-js-modal"}]},{type:a,value:" : my package of choice to implement modals in vue"}]},{type:a,value:c},{type:b,tag:k,props:{},children:[{type:b,tag:d,props:{href:"https:\u002F\u002Fgithub.com\u002Fnuxt-community\u002Ftailwindcss-module",rel:[f,g,h],target:i},children:[{type:a,value:"nuxt-tailwind"}]},{type:a,value:" : Since I discovered it : my go-to tool regarding handling UI"}]},{type:a,value:c}]},{type:a,value:c},{type:b,tag:m,props:{id:D},children:[{type:b,tag:d,props:{href:"#to-sum-up",ariaHidden:n,tabIndex:o},children:[{type:b,tag:p,props:{className:[q,r]},children:[]}]},{type:a,value:E}]},{type:a,value:c},{type:b,tag:e,props:{},children:[{type:a,value:"This project has been an excellent opportunity to experience a headless CMS and Server-side rendering. Prismic is an excellent service and I will use it again. Nuxt.js is still the best versatile framework to build website on top of Vue (though I also think "},{type:b,tag:d,props:{href:"https:\u002F\u002Fgridsome.org\u002F",rel:[f,g,h],target:i},children:[{type:a,value:"Gridsome"}]},{type:a,value:" is an excellent option for static sites). Forms is always something complex to implement but I found a pattern that helps me deal with such complexity."}]}]},excerpt:{type:F,children:[{type:b,tag:e,props:{},children:[{type:a,value:G},{type:b,tag:d,props:{href:H,rel:[f,g,h],target:i},children:[{type:a,value:I}]},{type:a,value:J}]}]},dir:"\u002Fposts",path:"\u002Fposts\u002Ftesting-a-headless-architecture-with-nuxt-prismic",extension:".md",updatedAt:"2025-10-10T15:29:17.528Z"},relatedPosts:[{title:"Red Teamer: Building a Button-Based AI Chatbot Game",type:j,imgCover:"red-teamer-building-a-button-based-ai-chatbot-game",tags:["game",L,"framer-motion","Tailwind","Figma",t,"cinema 4D","AI",j],createdAt:"2025-09-07T00:00:00.000Z",path:"\u002Fposts\u002Fred-teamer-building-a-button-based-ai-chatbot-game"},{title:"Switching from Vue to React",type:j,imgCover:"switching-from-vue-to-react",tags:["vue",s,"react",L,t,M,j],createdAt:"2021-02-28T00:00:00.000Z",path:"\u002Fposts\u002Fswitching-from-vue-to-react"},{title:"Quick review of Maizzle: the Tailwindcss email framework",type:j,imgCover:"quick-review-of-maizzle-the-tailwindcss-email-framework",tags:["email",M,j],createdAt:"2020-09-20T00:00:00.000Z",path:"\u002Fposts\u002Fquick-review-of-maizzle-the-tailwindcss-email-framework"},{title:"Nuxt.js puzzle game development - WIP#4",type:j,imgCover:"nuxt-js-puzzle-game-development-wip4",tags:[s,"cordova","games",j],createdAt:"2019-12-27T00:00:00.000Z",path:"\u002Fposts\u002Fnuxt-js-puzzle-game-development-wip4"}]}],fetch:[{counter:l},{counter:1},{counter:15},{counter:31},{counter:71}],mutations:[]}}("text","element","\n","a","p","nofollow","noopener","noreferrer","_blank","article","li",2,"h2","true",-1,"span","icon","icon-link","nuxt","devs","testing-a-headless-architecture-with-nuxt-prismic","prismic-as-headless-cms","Prismic as headless CMS","server-side-rendering-with-nuxt","Server-side rendering with Nuxt","mastering-complex-forms-using-phpnode","Mastering complex forms using php\u002Fnode","vue-library-round-up","Vue library round-up","to-sum-up","To sum up","root","This last month, I had the opportunity to finally test a headless architecture for a B2B single page website ","https:\u002F\u002Fmarketpay.eu","marketpay.eu",".\nThe page content should be editable by external contributors using a content management system.","ul","next","miscs")));